test_suite:
const trafficConfig = {
  initial: 'red',
  states: {
    red: { on: { NEXT: 'green' } },
    green: { on: { NEXT: 'yellow' } },
    yellow: { on: { NEXT: 'red' } },
  }
};

test('starts in initial state', () => {
  const { result } = renderHook(() => useStateMachine(trafficConfig));
  expect(result.current.state).toBe('red');
});

test('transitions on valid event', () => {
  const { result } = renderHook(() => useStateMachine(trafficConfig));
  act(() => result.current.send('NEXT'));
  expect(result.current.state).toBe('green');
});

test('multiple transitions', () => {
  const { result } = renderHook(() => useStateMachine(trafficConfig));
  act(() => result.current.send('NEXT'));
  act(() => result.current.send('NEXT'));
  expect(result.current.state).toBe('yellow');
});

test('invalid event leaves state unchanged', () => {
  const { result } = renderHook(() => useStateMachine(trafficConfig));
  act(() => result.current.send('UNKNOWN_EVENT'));
  expect(result.current.state).toBe('red');
});

// __hidden__
test('cycles back to initial state', () => {
  const { result } = renderHook(() => useStateMachine(trafficConfig));
  act(() => result.current.send('NEXT'));
  act(() => result.current.send('NEXT'));
  act(() => result.current.send('NEXT'));
  expect(result.current.state).toBe('red');
});

solution:
import { useReducer } from 'react';

interface StateMachineConfig {
  initial: string;
  states: Record<string, { on: Record<string, string> }>;
}

interface StateMachineResult {
  state: string;
  send: (event: string) => void;
}

export function useStateMachine(config: StateMachineConfig): StateMachineResult {
  const [state, dispatch] = useReducer((current: string, event: string) => {
    const transitions = config.states[current]?.on ?? {};
    return transitions[event] ?? current;
  }, config.initial);

  return { state, send: dispatch };
}
